local RouletteMaker = {}
local PRODUCTS = {
    simple_wood_roulette = { name = "Preprost lesen rulet", woodCost = 3, ironCost = 1, time = 5, cost = 100, happiness = 3, prestige = 2, description = "Preprost lesen rulet za krčme." },
    brass_wheel_roulette = { name = "Medeninasto kolo rulet", woodCost = 3, brassCost = 2, ironCost = 1, time = 8, cost = 280, happiness = 4, prestige = 5, description = "Medeninasto kolo rulet za trgovce." },
    silver_marker_roulette = { name = "Srebrnooznačevalni rulet", woodCost = 3, silverCost = 1, brassCost = 2, ironCost = 1, time = 11, cost = 680, happiness = 5, prestige = 10, description = "Srebrnooznačevalni rulet za plemiče." },
    gold_trimmed_roulette = { name = "Zlatookrasni rulet", woodCost = 3, goldCost = 1, silverCost = 1, brassCost = 2, ironCost = 1, time = 15, cost = 1500, happiness = 6, prestige = 18, description = "Zlatookrasni rulet za visoke plemiče." },
    jewel_set_roulette = { name = "Draguljasta rulet", woodCost = 3, goldCost = 2, silverCost = 1, brassCost = 2, ironCost = 1, jewelCost = 1, time = 19, cost = 3200, happiness = 8, prestige = 30, description = "Rulet z draguljem za visoko plemstvo." },
    royal_grand_roulette = { name = "Kraljevski veliki rulet", woodCost = 5, goldCost = 3, silverCost = 2, brassCost = 2, ironCost = 1, jewelCost = 2, pearlCost = 2, time = 26, cost = 7000, happiness = 14, prestige = 62, description = "Veliki kraljevski rulet z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    roulette_workshop = { name = "Ruletna delavnica", cost = { gold = 260, wood = 140, stone = 120, iron = 4 }, upkeep = 6, qualityBonus = 5 },
    gaming_loft = { name = "Igralna podstrešje", cost = { gold = 950, wood = 280, stone = 240, brass = 6, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    master_roulette_atelier = { name = "Mojstrski ruletni atelje", cost = { gold = 2700, wood = 380, stone = 480, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_casino_palace = { name = "Kraljevska igralniška palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
RouletteMaker.woodStock = 16; RouletteMaker.ironStock = 10; RouletteMaker.brassStock = 12; RouletteMaker.silverStock = 6; RouletteMaker.goldStock = 6; RouletteMaker.jewelStock = 4; RouletteMaker.pearlStock = 4
RouletteMaker.productStock = {}; RouletteMaker.buildings = {}; RouletteMaker.maker = nil; RouletteMaker.activeMaking = {}; RouletteMaker.totalProducts = 0; RouletteMaker.dayTimer = 0
function RouletteMaker.init() RouletteMaker.woodStock=16; RouletteMaker.ironStock=10; RouletteMaker.brassStock=12; RouletteMaker.silverStock=6; RouletteMaker.goldStock=6; RouletteMaker.jewelStock=4; RouletteMaker.pearlStock=4; RouletteMaker.productStock={}; RouletteMaker.buildings={}; RouletteMaker.maker=nil; RouletteMaker.activeMaking={}; RouletteMaker.totalProducts=0; RouletteMaker.dayTimer=0; print("[RouletteMaker] Royal Roulette Maker System initialized (6 products, 4 buildings)") end
function RouletteMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RouletteMaker.maker={name=n or ("Ruletar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ruletar najet: %s (spretnost: %d)",RouletteMaker.maker.name,s),"success") end; return true end
function RouletteMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RouletteMaker.build(id) local ok,e=RouletteMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RouletteMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RouletteMaker.getQualityBonus() local b=0; for _,bd in ipairs(RouletteMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RouletteMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and RouletteMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and RouletteMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and RouletteMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and RouletteMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RouletteMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RouletteMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and RouletteMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #RouletteMaker.buildings==0 then return false,"Potrebna ruletna delavnica" end; if not RouletteMaker.maker then return false,"Potreben ruletar" end; return true end
function RouletteMaker.make(pt,qty) qty=qty or 1; local ok,e=RouletteMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then RouletteMaker.woodStock=RouletteMaker.woodStock-d.woodCost*qty end; if d.ironCost then RouletteMaker.ironStock=RouletteMaker.ironStock-d.ironCost*qty end; if d.brassCost then RouletteMaker.brassStock=RouletteMaker.brassStock-d.brassCost*qty end; if d.silverCost then RouletteMaker.silverStock=RouletteMaker.silverStock-d.silverCost*qty end; if d.goldCost then RouletteMaker.goldStock=RouletteMaker.goldStock-d.goldCost*qty end; if d.jewelCost then RouletteMaker.jewelStock=RouletteMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then RouletteMaker.pearlStock=RouletteMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if RouletteMaker.maker then t=math.max(1,t-math.floor(RouletteMaker.maker.skill/12)) end; table.insert(RouletteMaker.activeMaking,{id="roulette_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RouletteMaker.completeMaking(m) local q=1.0+(RouletteMaker.getQualityBonus()/100); if RouletteMaker.maker then q=q+(RouletteMaker.maker.skill/140) end; q=math.min(2.5,q); RouletteMaker.productStock[m.productType]=(RouletteMaker.productStock[m.productType] or 0)+m.quantity; RouletteMaker.totalProducts=RouletteMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RouletteMaker.maker then RouletteMaker.maker.itemsMade=RouletteMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then RouletteMaker.maker.skill=math.min(100,RouletteMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rulet izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"roulette.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function RouletteMaker.update(dt) if not _G.state then return end; RouletteMaker.dayTimer=RouletteMaker.dayTimer+dt; if RouletteMaker.dayTimer>=30 then RouletteMaker.dayTimer=0; for i=#RouletteMaker.activeMaking,1,-1 do local m=RouletteMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RouletteMaker.completeMaking(m); table.remove(RouletteMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RouletteMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RouletteMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RouletteMaker.getStats() return {woodStock=RouletteMaker.woodStock,ironStock=RouletteMaker.ironStock,brassStock=RouletteMaker.brassStock,silverStock=RouletteMaker.silverStock,goldStock=RouletteMaker.goldStock,jewelStock=RouletteMaker.jewelStock,pearlStock=RouletteMaker.pearlStock,productStock=RouletteMaker.productStock,numBuildings=#RouletteMaker.buildings,hasMaker=RouletteMaker.maker~=nil,makerName=RouletteMaker.maker and RouletteMaker.maker.name or "—",makerSkill=RouletteMaker.maker and RouletteMaker.maker.skill or 0,activeMaking=#RouletteMaker.activeMaking,totalProducts=RouletteMaker.totalProducts} end
return RouletteMaker
